"use client";

import { useState } from "react";
import { UploadDropzone } from "@/components/shared/UploadDropzone";
import { ProgressState, ResultCard, ErrorState } from "@/components/shared/StateCards";
import { ToolMetadata } from "@/config/tools";

type FlowState = "upload" | "processing" | "result" | "error";

interface ToolWorkspaceProps {
  tool: ToolMetadata;
}

export function ToolWorkspace({ tool }: ToolWorkspaceProps) {
  const [flowState, setFlowState] = useState<FlowState>("upload");
  const [fileName, setFileName] = useState<string>("");

  const handleUpload = (files: FileList | null) => {
    if (files && files[0]) {
      const file = files[0];
      
      // Enforce file size limit based on tool config
      if (file.size > tool.maxSizeMB * 1024 * 1024) {
        setFlowState("error");
        return;
      }
      
      setFileName(file.name);
      setFlowState("processing");
      
      // Simulate processing time
      setTimeout(() => {
        setFlowState("result");
      }, 3000);
    }
  };

  const handleRetry = () => {
    setFlowState("upload");
    setFileName("");
  };

  return (
    <div className="my-12">
      {flowState === "upload" && (
        <UploadDropzone 
          onUpload={handleUpload} 
          accept={tool.accept} 
          maxSizeMB={tool.maxSizeMB} 
        />
      )}
      
      {flowState === "processing" && (
        <ProgressState fileName={fileName} />
      )}
      
      {flowState === "result" && (
        <ResultCard fileName={fileName} savedBytes="Processed File" />
      )}
      
      {flowState === "error" && (
        <ErrorState 
          message={`The file exceeds the maximum allowed size of ${tool.maxSizeMB}MB for free accounts. Please upgrade to Pro to process larger files.`}
          onRetry={handleRetry} 
        />
      )}
    </div>
  );
}
